mapper.select:

where 1=1

    and d.source_code = #{query.sourceCode}


    and d.source_name like concat('%', #{query.sourceName}, '%')


    and d.target_code = #{query.targetCode}


    and d.target_name like concat('%', #{query.targetName}, '%')


    and d.status = #{query.status}


    and d.year = #{query.year}


    and d.creator = #{query.creator}


    and (d.source_name like concat('%', #{query.keyword}, '%')
         or d.target_name like concat('%', #{query.keyword}, '%')
         or d.source_code like concat('%', #{query.keyword}, '%')
         or d.target_code like concat('%', #{query.keyword}, '%'))


    and d.create_time >= #{query.startTime}


    and d.create_time <= #{query.endTime}

order by d.create_time desc


where 1=1
    and d.status != '0'

    and d.source_code = #{query.sourceCode}


    and d.source_name like concat('%', #{query.sourceName}, '%')


    and d.target_code = #{query.targetCode}


    and d.target_name like concat('%', #{query.targetName}, '%')


    and d.status = #{query.status}


    and d.year = #{query.year}


    and d.creator = #{query.creator}


    and (d.source_name like concat('%', #{query.keyword}, '%')
    or d.target_name like concat('%', #{query.keyword}, '%')
    or d.source_code like concat('%', #{query.keyword}, '%')
    or d.target_code like concat('%', #{query.keyword}, '%'))


    and d.create_time >= #{query.startTime}


    and d.create_time <= #{query.endTime}

order by d.create_time desc
